def number_lessons(apps, schema_editor):
    """Give every existing lesson its place: the order it was sent in, which
    is the order courses played them before positions existed."""
    ProviderVideo = apps.get_model("providers", "ProviderVideo")
    current, number = None, 0
    for video in ProviderVideo.objects.order_by("provider_id", "created_at", "pk").only(
        "pk", "provider_id"
    ):
        if video.provider_id != current:
            current, number = video.provider_id, 0
        number += 1
        ProviderVideo.objects.filter(pk=video.pk).update(position=number)


